@startuml

class SensorController {
}

class Apartment {
  +address : string
}

class Inhabitant {
  +username : string
  +password : string
}

class Room {
  +description : string
}

abstract class Sensor {
  +vendorID : string
  +description : string
  +unit : Unit
}

class TemperatureSensor extends Sensor {
  +min : float
  +max : float
}

class PowerSensor extends Sensor {
  +counterReading : float
}

class MeasuredValue {
  +timestamp : datetime
  +value : float
}

class EMonitor {
}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" -- "1" Apartment : manages
Apartment "1" *-- "2..*" Room : consists of
Apartment "0..1" -- "1" EMonitor : monitored by
Apartment "1" -- "*" Inhabitant : has
Inhabitant "0..1" -- "1" SensorController : logs on to
Inhabitant "1" -- "*" Sensor : configures
Room "1" *-- "*" Sensor : contains
Sensor "1" *-- "*" MeasuredValue : records
Sensor "1" --> "0..1" MeasuredValue : lastValue

@enduml

